-- ============================================================================
-- PARTIE 16 — Contenu du module 4 « Jeu, exploration, espace » (3 séquences)
-- Source : Projet pédagogique Koalakids (environnement ludique sécurisant et
-- stimulant, posture « phare », étayer sans guider, objets identiques, circulation libre).
-- Script reconstitué à partir de la base (contenu publié).
-- Relançable : la trame est remplacée, les blocs ne sont ajoutés qu'une fois.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 16.1a Trame de la séquence 1/3 (Apport). Attendu : 1 ligne modifiée.
-- ---------------------------------------------------------------------------
update public.module
set accroche = $kk$L'adulte organise l'environnement, puis se place à côté de l'enfant : il étaye son jeu, il ne le guide pas.$kk$,
    trame = coalesce(trame, '{}'::jsonb) || $kk${"objectif": "À la fin, chacun est capable de dire ce que l'adulte organise (l'environnement de jeu) et ce qu'il fait pendant que l'enfant joue (se placer à ses côtés, étayer sans guider).", "public": "Toute l'équipe du site", "animateur": "Coordinatrice pédagogique ou référente du site", "socle": {"bloc": 2, "attendu": "Jeu, exploration et aménagement de l'espace"}, "duree_min": 45, "materiel": ["Fiche « Trois postures » (1 par personne)", "Paperboard", "Fiche de trace"], "deroule": [{"de": 0, "a": 5, "nom": "Ouverture", "consignes": ["Rappeler l'objectif de la séance.", "Présenter les 3 séances du module : apport, analyse d'une situation vécue, test d'une pratique.", "Chacun pense à un moment de jeu de la semaine où un enfant était pleinement absorbé, sans le raconter."]}, {"de": 5, "a": 15, "nom": "Apport", "message": "L'adulte organise l'environnement de jeu, puis se place à côté de l'enfant : il étaye son jeu, il ne le guide pas.", "idees": ["Pour apprendre, le jeune enfant a besoin de la présence de l'adulte pour éclairer et étayer son jeu, et d'objets qui lui permettent de faire de nombreuses expériences. Aucun résultat, réussite ou échec, n'est attendu de lui.", "L'adulte organise un environnement sécurisant et stimulant : au moins deux propositions de jeu ouvertes, un professionnel stable et disponible sur chacune, des objets en plusieurs exemplaires identiques pour favoriser l'imitation et éviter les conflits. Pas de liberté sans cadre.", "Posture « phare » : l'adulte se place à côté de l'enfant, s'intéresse à ce qu'il fait et à la façon dont il s'y prend, met des mots sur ses actions. L'enfant reste l'auteur de son jeu : on étaye, on ne guide pas."], "support": "Projet pédagogique Koalakids, « Comment organiser un environnement ludique sécurisant et stimulant ? »."}, {"de": 15, "a": 30, "nom": "Analyse d'une situation vécue sur le site", "consigne": "Choisir un moment de jeu vécu cette semaine sur le site, sans nommer l'enfant. On analyse ce que fait l'adulte, pas ce qu'est l'enfant.", "questions": ["Que s'est-il passé ? (ce que l'enfant a fait, ce que l'adulte a fait)", "Qu'est-ce que l'enfant cherchait à découvrir ou à comprendre ?", "L'environnement lui permettait-il de jouer (objets, espace, adulte disponible) ?", "Que faire autrement ?"], "consignes": ["Dans la trace écrite, on n'écrit ni nom d'enfant ni nom de collègue."]}, {"de": 30, "a": 40, "nom": "Mise en pratique", "consigne": "Un engagement concret par personne, à tester pendant la semaine et à raconter à la séance 3.", "amorce": "Cette semaine, je…", "consignes": ["Exemple : mettre des mots sur ce que fait un enfant, sans lui dire comment jouer.", "Exemple : ramasser les objets éparpillés et réorganiser une proposition de jeu.", "Exemple : observer un enfant jouer et noter comment il s'y prend."]}, {"de": 40, "a": 45, "nom": "Clôture", "consignes": ["Tour de table : un mot sur ce que je retiens.", "Remplir la trace écrite (3 à 5 lignes), sans nom d'enfant.", "Annoncer la séance 2/3 : analyse d'une situation de jeu vécue, avec un focus sur étayer ou guider."]}], "regles": ["Un message par séance.", "Situations réelles du site.", "Bienveillance : on analyse des pratiques, pas des personnes.", "Toujours finir par un engagement."]}$kk$::jsonb
where titre like 'Module 4 % 1/3 %';
-- FIN 16.1a

-- ---------------------------------------------------------------------------
-- 16.1b Blocs de la séquence 1/3. Attendu : 5 lignes (0 si déjà ajoutés).
-- ---------------------------------------------------------------------------
insert into public.bloc(module_id, type, contenu, ordre)
select m.id, v.type, v.contenu::jsonb, v.ordre
from public.module m
cross join (values
  (0,'texte',$kk${"titre": "Organiser, puis accompagner", "paragraphes": ["Un jeune enfant ne joue pas seul et dans n'importe quelles conditions. Il a besoin à la fois de **sécurité affective** et d'**aventures ludiques** : un environnement bien pensé, et un adulte présent à ses côtés.", "Cette première séance pose un repère : l'adulte organise l'environnement, puis il se place à côté de l'enfant. **L'enfant reste l'auteur de son jeu.**"]}$kk$),
  (1,'citation',$kk${"texte": "« Il est agréable de passer du temps avec les enfants dans une atmosphère paisible toute de douceur et de rires, faite de premières tentatives enjouées et d'étonnements, de joies pures et lumineuses. »\nJanusz Korczak"}$kk$),
  (2,'retenir',$kk${"titre": "À retenir", "points": ["**Aucun résultat attendu :** pas de commande de type « travail », ni de réussite ou d'échec à viser.", "**L'adulte organise :** au moins deux propositions de jeu, un professionnel stable sur chacune, des objets en plusieurs exemplaires identiques.", "**L'adulte étaye, il ne guide pas :** il se place à côté de l'enfant, s'intéresse à ce qu'il fait et met des mots sur ses actions."]}$kk$),
  (3,'reflexion',$kk${"question": "Pensez à un moment de jeu de cette semaine où un enfant était pleinement absorbé. Qu'est-ce qui le permettait ? Où était l'adulte ?", "sous_titre": "Il n'y a pas de bonne réponse : on cherche à comprendre ce qui aide l'enfant à jouer.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$),
  (4,'essayer',$kk${"label": "À essayer cette semaine", "titre": "Être un phare, trois gestes", "etapes": [{"titre": "Me placer à côté.", "texte": "Je m'installe à la hauteur de l'enfant, sans diriger son jeu."}, {"titre": "M'intéresser.", "texte": "Je regarde ce qu'il fait et la façon dont il s'y prend."}, {"titre": "Mettre des mots.", "texte": "Je dis ce que je vois : « Tu fais rouler la balle dans le tube. »"}], "note": "Choisissez un seul de ces gestes et testez-le toute la semaine."}$kk$)
) as v(ordre, type, contenu)
where m.titre like 'Module 4 % 1/3 %'
  and not exists (select 1 from public.bloc b where b.module_id = m.id);
-- FIN 16.1b

-- ---------------------------------------------------------------------------
-- 16.2a Trame de la séquence 2/3 (Analyse d'une situation vécue). Attendu : 1 ligne modifiée.
-- ---------------------------------------------------------------------------
update public.module
set accroche = $kk$Étayer ou guider ? On regarde ce que l'adulte a fait, pas ce que l'enfant aurait dû faire.$kk$,
    trame = coalesce(trame, '{}'::jsonb) || $kk${"objectif": "À la fin, chacun est capable de repérer dans une situation de jeu vécue sur le site si l'adulte a étayé ou guidé l'enfant, et de dire ce qu'il ferait autrement.", "public": "Toute l'équipe du site", "animateur": "Coordinatrice pédagogique ou référente du site", "socle": {"bloc": 2, "attendu": "Jeu, exploration et aménagement de l'espace"}, "duree_min": 45, "materiel": ["Paperboard", "Fiche de trace"], "deroule": [{"de": 0, "a": 5, "nom": "Ouverture", "consignes": ["Rappeler l'objectif de la séance.", "Retour sur la semaine : chacun dit en une phrase ce qu'il a essayé de son engagement « Cette semaine, je… », sans l'évaluer.", "Demander qui apporte la situation de jeu à analyser."]}, {"de": 5, "a": 15, "nom": "Apport", "message": "Étayer, ce n'est pas guider : l'enfant reste l'auteur de son jeu.", "idees": ["Aucune commande de type « travail » : on évite les propositions qui guident le jeu (« si tu donnais à manger à ta poupée ») ou qui attendent une production (« si tu faisais un joli dessin pour maman »).", "On respecte ses essais : un râteau pour coiffer une poupée, une passoire en chapeau. L'enfant cherche à comprendre les objets, il n'est ni fou ni idiot.", "On lui fait savoir qu'on a compris l'intérêt de son jeu plutôt que de le féliciter : les « Bravo » propulsent l'enfant dans le système échec ou réussite."], "support": "Projet pédagogique Koalakids, « Soutenir la curiosité naturelle des enfants ainsi que leur action et suivre l'enfant dans son jeu »."}, {"de": 15, "a": 30, "nom": "Analyse d'une situation vécue sur le site", "consigne": "Choisir un moment de jeu vécu cette semaine sur le site, sans nommer l'enfant. On regarde si l'adulte a étayé ou guidé.", "questions": ["Que s'est-il passé ? (ce que l'enfant a fait, ce que l'adulte a dit ou fait)", "Qu'est-ce que l'enfant cherchait à comprendre ou à découvrir ?", "Ai-je étayé son jeu ou l'ai-je guidé ?", "Que faire autrement ?"], "consignes": ["Dans la trace écrite, on n'écrit ni nom d'enfant ni nom de collègue."]}, {"de": 30, "a": 40, "nom": "Mise en pratique", "consigne": "Un engagement concret par personne, à tester pendant la semaine et à raconter à la séance 3.", "amorce": "Cette semaine, je…", "consignes": ["Exemple : me placer à côté d'un enfant et mettre des mots sur ses actions.", "Exemple : accepter qu'un enfant détourne un objet sans le reprendre.", "Exemple : remplacer un « Bravo » par ce que j'ai vu l'enfant faire."]}, {"de": 40, "a": 45, "nom": "Clôture", "consignes": ["Tour de table : un mot sur ce que je retiens.", "Remplir la trace écrite (3 à 5 lignes), sans nom d'enfant.", "Annoncer la séance 3/3 : retour d'expérience sur la pratique testée, avec un focus sur l'organisation de l'espace de jeu."]}], "regles": ["Un message par séance.", "Situations réelles du site.", "Bienveillance : on analyse des pratiques, pas des personnes.", "Toujours finir par un engagement."]}$kk$::jsonb
where titre like 'Module 4 % 2/3 %';
-- FIN 16.2a

-- ---------------------------------------------------------------------------
-- 16.2b Blocs de la séquence 2/3. Attendu : 5 lignes (0 si déjà ajoutés).
-- ---------------------------------------------------------------------------
insert into public.bloc(module_id, type, contenu, ordre)
select m.id, v.type, v.contenu::jsonb, v.ordre
from public.module m
cross join (values
  (0,'texte',$kk${"titre": "Étayer ou guider ?", "paragraphes": ["Quand un enfant joue, l'adulte est tenté de lui montrer comment faire, de proposer une suite, de le féliciter. Pourtant, c'est l'enfant qui sait ce qui l'intéresse. **La présence de l'adulte est une condition, mais son attitude doit étayer l'enfant, pas le guider.**", "Cette séance propose d'analyser une situation de jeu en regardant ce que l'adulte a fait, jamais ce que l'enfant aurait dû faire."]}$kk$),
  (1,'scenes',$kk${"titre": "Trois situations que vous reconnaîtrez", "items": [{"lettre": "A", "titre": "On lui propose un but", "texte": "Adam empile des cubes. Un collègue lui dit : « Et si tu faisais une jolie tour pour maman ? »", "analyse": "la proposition guide le jeu et attend une production. Adam avait son propre projet. On peut s'asseoir près de lui, s'intéresser à ce qu'il fait et mettre des mots sur ses actions : « Tu poses un cube sur l'autre. »"}, {"lettre": "B", "titre": "Il détourne un objet", "texte": "Léna met une passoire sur sa tête. Un collègue la reprend : « Non, ça, c'est pour la dînette. »", "analyse": "l'enfant n'est ni fou ni idiot : il cherche à comprendre les caractéristiques de l'objet. On respecte ses essais, on peut sourire et décrire ce qu'elle fait, sans corriger l'usage qu'elle en fait."}, {"lettre": "C", "titre": "Tout le monde applaudit", "texte": "Zoé pose le dernier anneau sur la tige. Les adultes applaudissent : « Bravo, tu as réussi ! »", "analyse": "un « Bravo » propulse l'enfant dans le système réussite ou échec. Mieux vaut lui faire savoir qu'on a compris l'intérêt de son jeu : « Tu as mis tous les anneaux sur la tige. »"}]}$kk$),
  (2,'comparaison',$kk${"intro": "Pour accompagner un enfant qui joue.", "plutot": ["Me placer à côté de l'enfant et m'intéresser à ce qu'il fait.", "Mettre des mots sur ses actions.", "Accepter qu'il détourne les objets.", "Jouer au même jeu que lui quand il m'y invite."], "eviter": ["Guider son jeu ou attendre une production.", "Dire « Bravo » pour une réussite.", "Lui montrer comment jouer.", "Corriger l'usage qu'il fait d'un objet."]}$kk$),
  (3,'reflexion',$kk${"question": "Dans quelle situation de jeu vous arrive-t-il de guider plutôt que d'étayer ? Qu'est-ce qui vous y pousse ?", "sous_titre": "Il s'agit de décrire, pas de juger. Personne ne lira votre réponse.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$),
  (4,'essayer',$kk${"label": "À essayer pendant l'analyse", "titre": "Trois questions devant un jeu", "etapes": [{"titre": "Qu'est-ce que je vois ?", "texte": "Ce que fait l'enfant, ce que je fais, sans interpréter."}, {"titre": "Qu'est-ce qu'il cherche ?", "texte": "Ce qu'il découvre ou essaie de comprendre avec cet objet."}, {"titre": "Est-ce que j'étaye ?", "texte": "Je soutiens son jeu ou je le dirige : qu'est-ce que je change ?"}], "note": "On analyse la pratique, jamais la personne."}$kk$)
) as v(ordre, type, contenu)
where m.titre like 'Module 4 % 2/3 %'
  and not exists (select 1 from public.bloc b where b.module_id = m.id);
-- FIN 16.2b

-- ---------------------------------------------------------------------------
-- 16.3a Trame de la séquence 3/3 (Test d'une pratique et retour d'expérience). Attendu : 1 ligne modifiée.
-- ---------------------------------------------------------------------------
update public.module
set accroche = $kk$Peu d'objets, plusieurs identiques, un adulte stable sur chaque proposition : l'espace laisse l'enfant jouer.$kk$,
    trame = coalesce(trame, '{}'::jsonb) || $kk${"objectif": "À la fin, chacun est capable de dire ce qu'a changé la pratique testée dans l'espace de jeu, et l'équipe a choisi une pratique commune pour organiser les propositions de jeu.", "public": "Toute l'équipe du site", "animateur": "Coordinatrice pédagogique ou référente du site", "socle": {"bloc": 2, "attendu": "Jeu, exploration et aménagement de l'espace"}, "duree_min": 45, "materiel": ["Fiche de trace", "Engagements de la séance 2", "Paperboard"], "deroule": [{"de": 0, "a": 5, "nom": "Ouverture", "consignes": ["Rappeler l'objectif de la séance.", "Chacun relit son engagement de la séance 2 (« Cette semaine, je… »).", "Rappeler la règle : on raconte ce qu'on a fait, on ne se juge pas."]}, {"de": 5, "a": 15, "nom": "Apport", "message": "Peu d'objets, plusieurs identiques, un adulte stable sur chaque proposition : l'espace laisse l'enfant jouer.", "idees": ["Des objets en plusieurs exemplaires identiques favorisent l'imitation et évitent les conflits. Peu d'objets à la fois, pour que l'enfant puisse se concentrer : le voir, c'est le vouloir.", "On ramasse régulièrement les objets éparpillés, on réorganise les propositions et on les enrichit de nouveaux objets à des moments clés, pour garder l'équilibre entre régularité et nouveauté.", "Les enfants circulent librement dans toute la crèche, toute la journée, avec au moins deux propositions ouvertes et un professionnel stable sur chacune. Un environnement sans danger et sans trop d'interdits évite de dire « non » sans cesse."], "support": "Projet pédagogique Koalakids, « Que faire concrètement pour accompagner les enfants qui circulent librement dans la crèche dans leurs jeux ? »."}, {"de": 15, "a": 30, "nom": "Analyse d'une situation vécue sur le site (retour d'expérience)", "consigne": "Chacun raconte en une minute la pratique qu'il a testée. On cherche ce qui s'est passé, pas qui a bien ou mal fait.", "questions": ["Qu'ai-je testé, et dans quelle situation ?", "Qu'ont fait les enfants ? Qu'est-ce qui a changé dans leur jeu, même un peu ?", "Qu'est-ce qui a été difficile ?", "Que gardons-nous en équipe ? Que changeons-nous ?"]}, {"de": 30, "a": 40, "nom": "Mise en pratique", "consigne": "Choisir ensemble une pratique commune à tenir pendant deux semaines, puis un engagement par personne.", "amorce": "Cette semaine, je…", "consignes": ["Pratique commune : une phrase que chacun peut décrire de la même façon.", "Chacun s'engage sur un geste précis, noté sur la fiche de trace."]}, {"de": 40, "a": 45, "nom": "Clôture", "consignes": ["Tour de table : un mot sur ce que je retiens.", "Remplir la trace écrite (3 à 5 lignes), sans nom d'enfant.", "Tour de table : ce que je retiens du module 4. Annoncer le prochain module du programme et la date de la première séance."]}], "regles": ["Un message par séance.", "Situations réelles du site.", "Bienveillance : on analyse des pratiques, pas des personnes.", "Toujours finir par un engagement."]}$kk$::jsonb
where titre like 'Module 4 % 3/3 %';
-- FIN 16.3a

-- ---------------------------------------------------------------------------
-- 16.3b Blocs de la séquence 3/3. Attendu : 4 lignes (0 si déjà ajoutés).
-- ---------------------------------------------------------------------------
insert into public.bloc(module_id, type, contenu, ordre)
select m.id, v.type, v.contenu::jsonb, v.ordre
from public.module m
cross join (values
  (0,'texte',$kk${"titre": "Un espace qui laisse jouer", "paragraphes": ["Un espace de jeu n'est pas là pour tout montrer, mais pour **permettre à l'enfant de se concentrer** et de jouer avec les autres. Moins d'objets visibles, plusieurs exemplaires identiques, un adulte stable sur chaque proposition.", "Cette dernière séance sert à regarder ensemble ce que vous avez testé, et à choisir **une pratique commune** pour organiser vos propositions de jeu."]}$kk$),
  (1,'retenir',$kk${"titre": "À retenir", "points": ["**Plusieurs exemplaires identiques** favorisent l'imitation et évitent les conflits. Peu d'objets à la fois : le voir, c'est le vouloir.", "**Régularité et nouveauté :** on ramasse, on réorganise, on enrichit à des moments clés.", "**Libre circulation :** au moins deux propositions ouvertes, un professionnel stable sur chacune, peu d'interdits."]}$kk$),
  (2,'reflexion',$kk${"question": "Dans votre espace de jeu, qu'est-ce qui empêche le plus les enfants de se concentrer ? Que pourriez-vous retirer, regrouper ou dupliquer ?", "sous_titre": "Il n'y a pas de bonne réponse : on cherche ce qui aiderait le jeu.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$),
  (3,'essayer',$kk${"label": "À essayer après la séance", "titre": "Une pratique commune", "etapes": [{"titre": "La choisir ensemble.", "texte": "Un geste simple d'organisation, que chacun applique de la même façon."}, {"titre": "La tenir deux semaines.", "texte": "Sans chercher la perfection : on note ce qui marche et ce qui coince."}, {"titre": "En reparler en équipe.", "texte": "À la prochaine réunion, quelques minutes pour dire ce qu'on garde."}], "note": "Toute pratique commune se décrit en une phrase."}$kk$)
) as v(ordre, type, contenu)
where m.titre like 'Module 4 % 3/3 %'
  and not exists (select 1 from public.bloc b where b.module_id = m.id);
-- FIN 16.3b

-- ---------------------------------------------------------------------------
-- 16c Contrôle (lecture seule). Attendu : 3 séquences, blocs 5 / 5 / 4.
-- ---------------------------------------------------------------------------
select m.titre, m.publie, (m.trame->>'objectif') is not null as objectif_ok,
       (select count(*) from public.bloc b where b.module_id = m.id) as blocs
from public.module m where m.titre like 'Module 4 %/3 %' order by m.ordre;
-- FIN 16c
